def pattern(n):
    if n <= 0:
        return ''
    max_length = 2 * n - 1
    lines = []
    for i in range(n):
        s = ''.join(str(x % 10) for x in range(1, i + 2)) + ''.join(str(x % 10) for x in range(i, 0, -1))
        lines.append(s.center(max_length))
    lines.extend(reversed(lines[:-1]))
    return '\n'.join(lines)
